    host: string;
    port: number;
    name: string;
    credentials: {
      username: string;
      password: string;  // Encrypted at rest
    };
  };
  security: {
    sslEnabled: boolean;
    rateLimit: number;
    tokenExpiryMinutes: number;
  };
  secrets: {
    apiSecret: string;  // Primary API signing secret
    encryptionKey: string;  // Data encryption key
  };
}

